async function discoverSite(root,fetcher=fetch,validate=async()=>{}){
 const origin=new URL(root).origin,queue=[origin+'/sitemap.xml'],seen=new Set(),urls=new Set(),warnings=[];
 const same=value=>{const u=new URL(value,origin);if(u.hostname.replace(/^www\./,'')!==new URL(origin).hostname.replace(/^www\./,'')||!['https:','http:'].includes(u.protocol))throw Error('Off-site sitemap excluded');return u};
 while(queue.length&&seen.size<12){let target=queue.shift();if(seen.has(target))continue;seen.add(target);try{let response;for(let hop=0;hop<5;hop++){const u=same(target);await validate(u.hostname);response=await fetcher(u.href,{redirect:'manual',signal:AbortSignal.timeout(15000)});if([301,302,303,307,308].includes(response.status)){target=same(new URL(response.headers.get('location'),u).href).href;continue}break}if(!response.ok)throw Error('HTTP '+response.status);if(Number(response.headers.get('content-length'))>1000000)throw Error('Sitemap too large');const reader=response.body.getReader();let raw='',size=0;const decoder=new TextDecoder();for(;;){const {done,value}=await reader.read();if(done)break;size+=value.length;if(size>1000000){await reader.cancel();throw Error('Sitemap too large')}raw+=decoder.decode(value,{stream:true})}raw+=decoder.decode();const locs=[...raw.matchAll(/<loc\b[^>]*>([\s\S]*?)<\/loc>/gi)].map(m=>m[1].trim().replace(/&amp;/g,'&').replace(/^<!\[CDATA\[|\]\]>$/g,''));for(const loc of locs){try{const u=same(loc);if(/<sitemapindex\b/i.test(raw))queue.push(u.href);else urls.add(u.href)}catch{}if(urls.size>=2000)break}if(urls.size>=2000){warnings.push('Sitemap discovery reached 2,000 URLs; linked-page discovery continues.');break}}catch(error){warnings.push(target+': '+error.message)}}
 if(queue.length)warnings.push('Some sitemap files were not read; linked-page discovery continues.');return {urls:[...urls],warnings};
}

